"""Build the local evidence gallery, separate from the two production documents."""
from pathlib import Path
import json
OUT=Path(__file__).resolve().parents[1]
manifest=json.loads((OUT/'site-inventory.json').read_text())
html='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>LENS Master 对齐与统一视觉审阅</title><style>body{margin:0;background:#0b1f33;color:#e8f0f7;font:15px/1.7 system-ui,sans-serif}main{max-width:1250px;margin:auto;padding:36px 24px}h1,h2{font-family:Georgia,serif;font-weight:400}a{color:#116e70}video{width:100%;max-height:720px;background:#05121e;border-radius:12px}section{margin:36px 0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}figure{color:#1e3a56;margin:0;background:white;border:1px solid #d8e4ea;border-radius:12px;overflow:hidden}figure img{display:block;width:100%;height:auto}figcaption{padding:12px 16px}select{margin:0 12px 18px 0;padding:10px;background:white;color:#1e3a56;border:1px solid #b8cfd9;border-radius:7px}.screens{display:grid;grid-template-columns:1fr 1fr;gap:20px}.screens.phone{grid-template-columns:repeat(3,minmax(0,1fr))}@media(max-width:700px){.grid,.screens,.screens.phone{grid-template-columns:1fr}main{padding:24px 16px}}</style><main><h1>LENS · Master 内容对齐与渲染修复</h1><p>对齐 Master 五部分内容，恢复原路径插画，统一深蓝/青色开场与页面、浅色科学图纸。<a href="REPORT.md">迁移报告</a> · <a href="after/validation-summary.json">完整验收</a> · <a href="../../docs/visual-refinement-workflow.md">更新后的流程</a></p><section><h2>真实浏览器录屏</h2><video controls preload="metadata" src="after/intro-demo-desktop.mp4"></video><p>由真实 Chromium 帧编码，仅为审阅材料；生产网站实时绘制 Canvas/SVG，不加载此视频。</p></section><section><h2>设计参考与取舍</h2><p>下列为真实生图参考，包含模型文字错误，不能当作最终界面或研究证据。采用 B 的视觉方向，保留原生内容与数据。</p><div class="grid"><figure><a href="design/direction-a.png"><img src="design/direction-a.png" loading="lazy" alt="生图方向 A"></a><figcaption>A：浅色统一方案，未选。</figcaption></figure><figure><a href="design/direction-b.png"><img src="design/direction-b.png" loading="lazy" alt="生图方向 B"></a><figcaption>B：深蓝框架和浅色图纸，选用。</figcaption></figure></div></section><section><h2>全部实际状态截图</h2><p id="count"></p><label>宽度 <select id="device"><option value="desktop">桌面 1440px</option><option value="mobile">手机 390px</option></select></label><label>类型 <select id="family"><option value="all">全部</option><option value="deck">展示基础页</option><option value="landscape">数据全貌</option><option value="story">核心发现</option><option value="publication">出版图</option><option value="code">代码视图</option><option value="discovery">更多发现</option><option value="library">图表探索</option></select></label><div class="screens" id="screens"></div></section><section><h2>基线与两轮反馈</h2><p>原始截图在 before/，第一轮实现在 iterations/round-1/，完整提示词在 design/prompts.json，最终截图和检查在 after/。第二轮生图针对真实首页和手机截图，只采纳层级、间距与配色，原 Master 内容和图形保持。</p></section></main><script>const routes=ROUTES;const device=document.querySelector('#device'),family=document.querySelector('#family'),screens=document.querySelector('#screens');function render(){const rows=routes.filter(r=>family.value==='all'||r.family===family.value);document.querySelector('#count').textContent=rows.length+' 个实际状态；另有 320px / 768px / 1366×768 正常动画浏览器绘制检查。';screens.classList.toggle('phone',device.value==='mobile');screens.replaceChildren();for(const r of rows){const f=document.createElement('figure'),a=document.createElement('a'),i=document.createElement('img'),c=document.createElement('figcaption');a.href='after/'+r.key+'-'+device.value+'.png';i.src=a.href;i.loading='lazy';i.alt=r.key;c.textContent=r.key+' · '+r.url;a.append(i);f.append(a,c);screens.append(f);}}device.onchange=family.onchange=render;render();</script></html>'''
(OUT/'index.html').write_text(html.replace('ROUTES',json.dumps(manifest['routes'],ensure_ascii=False)))
print('Evidence gallery ready:',OUT/'index.html')
